#include <iostream>
#include <cstring>
#include <queue>
#include <vector>
#include <cctype>
#include <algorithm>
#include <climits>
using namespace std;

using ll = long long;
const int INF = 0x3f3f3f3f;
const int MAX_NODES = 210;

struct Edge {
    int to, capacity, reverse_index;
    Edge(int t, int c, int r) : to(t), capacity(c), reverse_index(r) {}
};

vector<Edge> adj[MAX_NODES];
int level[MAX_NODES], progress[MAX_NODES];

void insert_edge(int u, int v, int cap) {
    adj[u].emplace_back(v, cap, adj[v].size());
    adj[v].emplace_back(u, 0, adj[u].size() - 1);
}

void compute_levels(int source) {
    memset(level, -1, sizeof(level));
    queue<int> q;
    q.push(source);
    level[source] = 0;
    while (!q.empty()) {
        int u = q.front(); q.pop();
        for (const auto& e : adj[u]) {
            if (e.capacity > 0 && level[e.to] < 0) {
                level[e.to] = level[u] + 1;
                q.push(e.to);
            }
        }
    }
}

int push_flow(int node, int sink, int bottleneck) {
    if (node == sink) return bottleneck;
    for (int& i = progress[node]; i < (int)adj[node].size(); ++i) {
        Edge& e = adj[node][i];
        if (e.capacity > 0 && level[node] < level[e.to]) {
            int pushed = push_flow(e.to, sink, min(bottleneck, e.capacity));
            if (pushed > 0) {
                e.capacity -= pushed;
                adj[e.to][e.reverse_index].capacity += pushed;
                return pushed;
            }
        }
    }
    return 0;
}

int compute_max_flow(int source, int sink) {
    int total_flow = 0;
    while (true) {
        compute_levels(source);
        if (level[sink] < 0) break;
        memset(progress, 0, sizeof(progress));
        int pushed;
        while ((pushed = push_flow(source, sink, INF)) > 0) {
            total_flow += pushed;
        }
    }
    return total_flow;
}

const int MOVES[4][2] = {{0,1},{0,-1},{1,0},{-1,0}};

int size, steps, source_node, sink_node;
int capacities[15][15], science[15][15], environment[65][15][15];
bool explored[15][15];
bool connectivity[65][15][15][15][15];

int encode(int x, int y, int type) {
    return (x-1)*size + y + type*size*size;
}

void explore(int origin_x, int origin_y, int cur_x, int cur_y, int depth) {
    explored[cur_x][cur_y] = true;
    connectivity[depth][origin_x][origin_y][cur_x][cur_y] = true;
    if (depth >= steps || environment[depth][cur_x][cur_y]) return;
    for (int d = 0; d < 4; ++d) {
        int nx = cur_x + MOVES[d][0], ny = cur_y + MOVES[d][1];
        if (nx < 1 || ny < 1 || nx > size || ny > size) continue;
        if (explored[nx][ny] || environment[depth][nx][ny]) continue;
        explore(origin_x, origin_y, nx, ny, depth + 1);
    }
}

void initialize() {
    for (int t = 1; t <= steps; ++t) {
        for (int x = 1; x <= size; ++x) {
            for (int y = 1; y <= size; ++y) {
                if (environment[t-1][x][y]) {
                    environment[t][x][y] = environment[t-1][x][y];
                } else {
                    for (int d = 0; d < 4; ++d) {
                        int nx = x + MOVES[d][0], ny = y + MOVES[d][1];
                        if (nx < 1 || ny < 1 || nx > size || ny > size) continue;
                        if (environment[t-1][nx][ny] == 2) {
                            environment[t][x][y] = 2;
                            break;
                        }
                    }
                }
            }
        }
    }
    for (int i = 1; i <= size; ++i) {
        for (int j = 1; j <= size; ++j) {
            if (science[i][j]) {
                memset(explored, 0, sizeof(explored));
                explore(i, j, i, j, 0);
            }
        }
    }
    for (int t = 1; t <= steps; ++t) {
        for (int x = 1; x <= size; ++x) {
            for (int y = 1; y <= size; ++y) {
                for (int xx = 1; xx <= size; ++xx) {
                    for (int yy = 1; yy <= size; ++yy) {
                        connectivity[t][x][y][xx][yy] |= connectivity[t-1][x][y][xx][yy];
                    }
                }
            }
        }
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    cin >> size >> steps;
    for (int i = 1; i <= size; ++i) {
        string line;
        cin >> line;
        for (int j = 1; j <= size; ++j) {
            char c = line[j-1];
            if (isdigit(c)) science[i][j] = c - '0';
            else if (c == 'Y') environment[0][i][j] = 1;
            else if (c == 'Z') environment[0][i][j] = 2;
        }
    }
    for (int i = 1; i <= size; ++i) {
        string line;
        cin >> line;
        for (int j = 1; j <= size; ++j) {
            char c = line[j-1];
            if (isdigit(c)) capacities[i][j] = c - '0';
        }
    }
    source_node = size * size * 2;
    sink_node = source_node - 1;
    initialize();
    for (int i = 1; i <= size; ++i) {
        for (int j = 1; j <= size; ++j) {
            if (science[i][j]) insert_edge(source_node, encode(i,j,0), science[i][j]);
            if (capacities[i][j]) insert_edge(encode(i,j,1), sink_node, capacities[i][j]);
        }
    }
    for (int x = 1; x <= size; ++x) {
        for (int y = 1; y <= size; ++y) {
            for (int xx = 1; xx <= size; ++xx) {
                for (int yy = 1; yy <= size; ++yy) {
                    if (science[x][y] && capacities[xx][yy] && connectivity[steps][x][y][xx][yy]) {
                        insert_edge(encode(x,y,0), encode(xx,yy,1), INF);
                    }
                }
            }
        }
    }
    cout << compute_max_flow(source_node, sink_node) << '\n';
    return 0;
}
